-- The refusal is a property of the column *being* an identity column, not of which
-- generation clause declared it: `ATExecColumnDefault` tests `attidentity`, which both
-- `ALWAYS` and `BY DEFAULT` set, so 18.6 answers the same 42601 for either. Every other
-- identity fixture in this family declares `ALWAYS`, so a gate keyed on that generation
-- alone passes all of them and lets this one through — and `BY DEFAULT` is the spelling
-- a SERIAL-replacement column carries, so it is the one a restore script is most likely
-- to aim a `SET DEFAULT nextval(...)` at.
-- @setup
CREATE TABLE sdbd_t (id INT GENERATED BY DEFAULT AS IDENTITY, b INT);
CREATE SEQUENCE sdbd_other;
-- @test
ALTER TABLE sdbd_t ALTER COLUMN id SET DEFAULT nextval('sdbd_other');
-- @expect-error: column is an identity column (42601)
